const statuses: OfferStatus[] = [
    "draft",
    "pendingApproval",
    "ready",
    "sent",
    "viewed",
    "accepted",
    "ordered",
    "rejected",
    "expired",
];

const statusAliases: Record<string, OfferStatus> = {
    draft: "draft",
    pendingapproval: "pendingApproval",
    ready: "ready",
    sent: "sent",
    viewed: "viewed",
    accepted: "accepted",
    ordered: "ordered",
    rejected: "rejected",
    expired: "expired",
};

export const normalizeOfferStatus = (value: CommercialOffer["status"]): OfferStatus => {
    if (typeof value === "number" && statuses[value]) {
        return statuses[value];
    }

    const numericValue = typeof value === "string" && /^\d+$/.test(value)
        ? Number(value)
        : Number.NaN;
    if (Number.isInteger(numericValue) && statuses[numericValue]) {
        return statuses[numericValue];
    }

    const normalized = String(value).replace(/[\s_-]+/g, "").toLowerCase();
    return statusAliases[normalized] ?? "draft";
};

