import React, {useMemo, useState} from "react";
import {
    Alert,
    Button,
    Chip,
    InputAdornment,
    LinearProgress,
    MenuItem,
    TextField,
} from "@mui/material";
import AddOutlinedIcon from "@mui/icons-material/AddOutlined";
import ArrowForwardOutlinedIcon from "@mui/icons-material/ArrowForwardOutlined";
import DescriptionOutlinedIcon from "@mui/icons-material/DescriptionOutlined";
import DashboardCustomizeOutlinedIcon from "@mui/icons-material/DashboardCustomizeOutlined";
import SearchOutlinedIcon from "@mui/icons-material/SearchOutlined";
import {useNavigate} from "react-router-dom";
import {
    EmptyState,
    MainDiv,
    PageHeader,
    PageSubtitle,
    PageTitle,
    PageTitleGroup,
    Surface,
    Toolbar,
    ToolbarActions,
} from "../../ui/commonStyled/commonStyled";
import {
    formatOfferDate,
    formatOfferMoney,
    normalizeOfferStatus,
    OfferStatus,
    offerStatusColors,
    offerStatusLabels,
} from "../../models/commercialOffer";
import {useGetCommercialOffersQuery} from "./commercialOffersApi";
import {
    DesktopCell,
    MetricCard,
    MetricLabel,
    MetricsGrid,
    MetricValue,
    OfferCard,
    OfferList,
    OfferNumber,
    SecondaryText,
} from "./commercialOfferStyles";

type StatusFilter = "all" | OfferStatus;

const CommercialOffersPage = () => {
    const navigate = useNavigate();
    const {data: offers = [], isLoading, isFetching, isError, refetch} = useGetCommercialOffersQuery();
    const [search, setSearch] = useState("");
    const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");

    const filteredOffers = useMemo(() => {
        const normalizedSearch = search.trim().toLocaleLowerCase("ru-RU");

        return [...offers]
            .filter((offer) => statusFilter === "all" || normalizeOfferStatus(offer.status) === statusFilter)
            .filter((offer) => !normalizedSearch || [offer.number, offer.customerName, offer.manager]
                .some((value) => value?.toLocaleLowerCase("ru-RU").includes(normalizedSearch)))
            .sort((left, right) => new Date(right.createdAt).getTime() - new Date(left.createdAt).getTime());
    }, [offers, search, statusFilter]);

    const metrics = useMemo(() => {
        const activeStatuses: OfferStatus[] = ["draft", "pendingApproval", "ready", "sent", "viewed", "accepted"];
        const activeOffers = offers.filter((offer) => activeStatuses.includes(normalizeOfferStatus(offer.status)));
        const customerActivity = offers.filter((offer) => ["viewed", "accepted", "ordered"]
            .includes(normalizeOfferStatus(offer.status)));

        return {
            total: offers.length,
            active: activeOffers.length,
            customerActivity: customerActivity.length,
            activeValue: activeOffers.reduce((sum, offer) => sum + offer.total, 0),
        };
    }, [offers]);

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>Коммерческие предложения</PageTitle>
                    <PageSubtitle>
                        Подготовьте предложение из актуального каталога, выпустите PDF и отправьте его клиенту.
                    </PageSubtitle>
                </PageTitleGroup>
                <ToolbarActions>
                    <Button
                        variant="outlined"
                        size="large"
                        startIcon={<DashboardCustomizeOutlinedIcon/>}
                        onClick={() => navigate("/commercialOffers/templates")}
                    >
                        Шаблоны
                    </Button>
                    <Button
                        variant="contained"
                        size="large"
                        startIcon={<AddOutlinedIcon/>}
                        onClick={() => navigate("/commercialOffers/new")}
                    >
                        Создать КП
                    </Button>
                </ToolbarActions>
            </PageHeader>

            <MetricsGrid>
                <MetricCard>
                    <MetricLabel>Всего предложений</MetricLabel>
                    <MetricValue>{metrics.total}</MetricValue>
                </MetricCard>
                <MetricCard>
                    <MetricLabel>В работе</MetricLabel>
                    <MetricValue>{metrics.active}</MetricValue>
                </MetricCard>
                <MetricCard>
                    <MetricLabel>Реакции клиентов</MetricLabel>
                    <MetricValue>{metrics.customerActivity}</MetricValue>
                </MetricCard>
                <MetricCard>
                    <MetricLabel>Сумма активных КП</MetricLabel>
                    <MetricValue>{formatOfferMoney(metrics.activeValue)}</MetricValue>
                </MetricCard>
            </MetricsGrid>

            <Surface>
                <Toolbar>
                    <TextField
                        size="small"
                        label="Поиск"
                        placeholder="Номер, клиент или менеджер"
                        value={search}
                        onChange={(event) => setSearch(event.target.value)}
                        sx={{width: {xs: "100%", sm: 340}}}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <SearchOutlinedIcon fontSize="small"/>
                                </InputAdornment>
                            ),
                        }}
                    />
                    <ToolbarActions>
                        <TextField
                            select
                            size="small"
                            label="Статус"
                            value={statusFilter}
                            onChange={(event) => setStatusFilter(event.target.value as StatusFilter)}
                            sx={{minWidth: 205}}
                        >
                            <MenuItem value="all">Все статусы</MenuItem>
                            {Object.entries(offerStatusLabels).map(([value, label]) => (
                                <MenuItem key={value} value={value}>{label}</MenuItem>
                            ))}
                        </TextField>
                        <Button variant="outlined" onClick={() => void refetch()} disabled={isFetching}>
                            Обновить
                        </Button>
                    </ToolbarActions>
                </Toolbar>

                {(isLoading || isFetching) && <LinearProgress sx={{mb: 1.5}}/>}
                {isError && (
                    <Alert severity="error" action={<Button onClick={() => void refetch()}>Повторить</Button>}>
                        Не удалось загрузить коммерческие предложения.
                    </Alert>
                )}

                {!isLoading && !isError && filteredOffers.length === 0 && (
                    <EmptyState>
                        <DescriptionOutlinedIcon sx={{fontSize: 44}}/>
                        <strong>{offers.length ? "Ничего не найдено" : "Коммерческих предложений пока нет"}</strong>
                        <span>{offers.length ? "Измените поиск или фильтр." : "Создайте первое КП для клиента."}</span>
                        {!offers.length && (
                            <Button variant="contained" onClick={() => navigate("/commercialOffers/new")}>
                                Создать КП
                            </Button>
                        )}
                    </EmptyState>
                )}

                <OfferList>
                    {filteredOffers.map((offer) => {
                        const status = normalizeOfferStatus(offer.status);
                        return (
                            <OfferCard key={offer.id} type="button" onClick={() => navigate(`/commercialOffers/${offer.id}`)}>
                                <div>
                                    <OfferNumber>{offer.number}</OfferNumber>
                                    <SecondaryText>Версия {offer.revisionNumber || "не выпущена"}</SecondaryText>
                                </div>
                                <DesktopCell>
                                    <OfferNumber>{offer.customerName}</OfferNumber>
                                    <SecondaryText>{offer.manager || "Менеджер не указан"}</SecondaryText>
                                </DesktopCell>
                                <DesktopCell>
                                    <Chip size="small" color={offerStatusColors[status]} label={offerStatusLabels[status]}/>
                                    {offer.deliveryPending && <SecondaryText>Отправка выполняется…</SecondaryText>}
                                </DesktopCell>
                                <DesktopCell>
                                    <OfferNumber>{formatOfferMoney(offer.total)}</OfferNumber>
                                    <SecondaryText>Действует до {formatOfferDate(offer.validUntil)}</SecondaryText>
                                </DesktopCell>
                                <ArrowForwardOutlinedIcon color="action"/>
                            </OfferCard>
                        );
                    })}
                </OfferList>
            </Surface>
        </MainDiv>
    );
};

export default CommercialOffersPage;
